function safeAwsError(error){
 if(error instanceof AwsConnectionError)return {code:error.code,message:error.message};
 const code=error?.name||"AWS_REQUEST_FAILED";
 if(["ExpiredToken","ExpiredTokenException","InvalidClientTokenId","UnrecognizedClientException","CredentialsProviderError","UnauthorizedException","InvalidGrantException","InvalidTokenException"].includes(code))return {code:"AWS_PROFILE_AUTH_FAILED",message:"Your AWS IAM Identity Center session has expired or been revoked. Connect to AWS again."};
 if(["ThrottlingException","TooManyRequestsException","RequestLimitExceeded"].includes(code))return {code:"AWS_THROTTLED",message:"AWS is temporarily rate limiting this request. Wait briefly, then refresh."};
 return {code:"AWS_REQUEST_FAILED",message:`AWS could not complete the request (${code}). Check the IAM Identity Center permission assignment and retry.`};
}

